class Typed:
    """Data descriptor: validates on assignment."""
    def __init__(self, kind):
        self.kind = kind
    def __set_name__(self, owner, name):    # called once at class creation
        self.name = name
        self.slot = "_" + name
    def __get__(self, obj, cls=None):
        if obj is None:
            return self                      # access on the class itself
        return getattr(obj, self.slot)
    def __set__(self, obj, value):
        if not isinstance(value, self.kind):
            raise TypeError(f"{self.name} must be {self.kind.__name__}")
        setattr(obj, self.slot, value)

class Person:
    name = Typed(str)
    age = Typed(int)
    def __init__(self, name, age):
        self.name = name
        self.age = age
    def hello(self):
        return "hi " + self.name

p = Person("Ada", 36)
print("name:", p.name, "age:", p.age)
try:
    p.age = "old"
except TypeError as e:
    print("error:", e)

# Functions are non-data descriptors: __get__ builds the bound method
bound = Person.__dict__["hello"].__get__(p, Person)
print("bound call:", bound())
print("same as p.hello():", bound() == p.hello())
print("property is a descriptor:", hasattr(property, "__set__"))
print("staticmethod returns raw fn:", staticmethod(len).__get__(p, Person) is len)

# Plugin registry with __init_subclass__ (preferred) and a metaclass (heavy).
class Plugin:
    registry = {}
    def __init_subclass__(cls, key=None, **kw):
        super().__init_subclass__(**kw)
        if key is None:
            raise TypeError(cls.__name__ + " needs key=")
        Plugin.registry[key] = cls          # runs when each subclass is defined

class Csv(Plugin, key="csv"):
    pass
class Json(Plugin, key="json"):
    pass

print("registry:", sorted(Plugin.registry))

class Meta(type):                           # a metaclass: the class of a class
    def __new__(mcs, name, bases, ns):
        ns["tag"] = name.upper()            # rewrite the class while building it
        return super().__new__(mcs, name, bases, ns)

class Thing(metaclass=Meta):
    pass

print("Thing.tag:", Thing.tag)
print("type(Thing):", type(Thing).__name__)
print("type(type):", type(type).__name__)   # type is its own metaclass
print("Meta is a subclass of type:", issubclass(Meta, type))

try:
    class Bad(Plugin):                       # no key -> rejected at class creation
        pass
except TypeError as e:
    print("error:", e)

import dis

G = 10

def demo(a):
    b = a + 1                # local
    def inner():
        return b + G         # b is a closure cell, G is global
    return inner() + 24 * 60 * 60

ops = {}
for ins in dis.get_instructions(demo):
    if ins.argval in ("a", "b", "G"):
        ops[(ins.opname, ins.argval)] = True
print("a in demo:", sorted(k for k in ops if k[1] == "a"))
print("b in demo:", sorted(k for k in ops if k[1] == "b"))
print("code names:", demo.__code__.co_varnames, demo.__code__.co_cellvars)
print("86400 folded constant:", 86400 in demo.__code__.co_consts)

def inner_code():
    for c in demo.__code__.co_consts:
        if hasattr(c, "co_code"):
            return c
inner = inner_code()
print("inner free vars:", inner.co_freevars)
print("inner has LOAD_DEREF:", "LOAD_DEREF" in {i.opname for i in dis.get_instructions(inner)})
print("inner has LOAD_GLOBAL:", "LOAD_GLOBAL" in {i.opname for i in dis.get_instructions(inner)})

# Swap does not build a tuple in modern CPython
swap = [i.opname for i in dis.get_instructions(compile("a, b = b, a", "s", "exec"))]
print("BUILD_TUPLE used for swap:", "BUILD_TUPLE" in swap)
